description:
Design a glitch filter that stabilizes an input signal by ensuring it remains consistent for a specified number of clock cycles before passing it to the output. The filter uses a shift register to sample the incoming signal and a counter to track how long the signal has been stable. If the signal maintains the same value for the defined threshold duration, it is considered stable, and the output reflects the input signal; otherwise, the output is set to LOW. This module effectively eliminates transient noise and fluctuations in the signal, making it suitable for applications that require clean and stable signals.
module top_module(
  input wire clk,        // Added clock input
  input wire signal_in,  // Declared as input wire
  output reg signal_out  // Changed output to reg
);

code:
module top_module(
  input wire clk,        // Added clock input
  input wire signal_in,  // Declared as input wire
  output reg signal_out  // Changed output to reg
);parameter threshold = 10; // number of clock cycles for the signal to remain stable

reg [threshold-1:0] shift_reg; // shift register to store sampled signals
reg [threshold-1:0] counter; // counter to count stable clock cycles

always @(posedge clk) begin
  // shift register to store sampled signals
  shift_reg <= {shift_reg[threshold-2:0], signal_in};

  // counter to count stable clock cycles
  if (shift_reg == {threshold{signal_in}}) begin
    if (counter < threshold) counter <= counter + 1;
  end else begin
    counter <= 0;
  end

  // output signal if stable for threshold clock cycles
  if (counter == threshold) begin
    signal_out <= signal_in;
  end else begin
    signal_out <= 0;
  end
end

endmodule

