module top_module(
    aclr,
    clock,
    data,
    rdreq,
    wrreq,
    almost_full,
    empty,
    full,
    q,
    usedw
);input aclr;
input clock;
input [15:0] data;
input rdreq;
input wrreq;
output almost_full;
output empty;
output full;
output [15:0] q;
output [3:0] usedw;

reg [15:0] fifo [0:14];
reg [3:0] head, tail;
wire [3:0] usedw = head - tail;
wire [3:0] next_head = head + 1;
wire [3:0] next_tail = tail + 1;
wire [3:0] next_next_tail = tail + 2;
wire [15:0] q = fifo[tail];
wire almost_full = (usedw >= 12);
wire empty = (usedw == 0);
wire full = (usedw == 15);

always @(posedge clock or posedge aclr) begin
    if (aclr) begin
        head <= 0;
        tail <= 0;
        fifo[0] <= 16'h0000;
    end else begin
        if (wrreq && !full) begin
            fifo[next_head] <= data;
            head <= next_head;
        end
        if (rdreq && !empty) begin
            tail <= next_tail;
        end
    end
end

endmodule

