Design a circuit that detects the position of the highest set bit in an 8-bit input. The module takes an 8-bit input and outputs a 3-bit register indicating the index of the most significant bit (MSB) that is set to 1, with 0 corresponding to the least significant bit (LSB). The output is updated on the positive edge of a detected signal that indicates any bit in the input is high. If no bits are set, the output defaults to 0. This functionality resembles a priority encoder focused on identifying the highest active bit in a binary number.
module top_module(
    input [7:0] in,
    output reg [2:0] pos
);

code:
module top_module(
    input [7:0] in,
    output reg [2:0] pos
);reg [2:0] pos_next;
wire highest_bit_detected;

// Combinational logic for detecting the highest bit
assign highest_bit_detected = (in[7] || in[6] || in[5] || in[4] || in[3] || in[2] || in[1] || in[0]);

always @(*) begin
    if (in[7]) pos_next = 3'b111;
    else if (in[6]) pos_next = 3'b110;
    else if (in[5]) pos_next = 3'b101;
    else if (in[4]) pos_next = 3'b100;
    else if (in[3]) pos_next = 3'b011;
    else if (in[2]) pos_next = 3'b010;
    else if (in[1]) pos_next = 3'b001;
    else if (in[0]) pos_next = 3'b000;
    else pos_next = 3'b000;
end

// Sequential logic for updating the output register
always @(posedge highest_bit_detected) begin
    pos <= pos_next;
end

endmodule

