description:
Implement a 4-bit binary counter that increments on each positive clock edge. When the counter reaches its maximum value (15 in binary, or 1111), it wraps around to zero. The counter can be asynchronously reset to zero when the reset signal is low. The current count value is output through the count_out signal.
module top_module(
    // Inputs
    reset,
    clk,
    // Outputs
    count_out
);

code:
module top_module(
    // Inputs
    reset,
    clk,
    // Outputs
    count_out
);// Input signals
    input reset;
    input clk;

    // Output signals
    output [3:0] count_out;

    // Internal signals
    reg [3:0] count;

    always @(posedge clk or negedge reset) begin
        if (!reset) begin
            count <= 4'b0;
        end else begin
            if (count == 4'b1111) begin
                count <= 4'b0;
            end else begin
                count <= count + 1;
            end
        end
    end

    assign count_out = count;

endmodule

