Design a clock divider module that takes a 50 MHz input clock signal and generates a 1 Hz output clock signal. The module uses a 32-bit counter to count the number of clock cycles and toggles the output clock (clk_1) every 50 million counts, effectively reducing the frequency of the input clock by a factor of 50 million. The circuit includes power supply signals to ensure proper operation within a digital design environment.
module top_module(
    input clk_50,
    output reg clk_1
);

code:
module top_module(
    input clk_50,
    output reg clk_1
);// Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    reg [31:0] counter = 0;

    always @(posedge clk_50) begin
        counter <= counter + 1;
        if (counter == 50000000) begin
            counter <= 0;
            clk_1 <= ~clk_1;
        end
    end

endmodule

