        output reg z);parameter A=0, B=1, C=2, D=3, E=4, F=5;
	reg [2:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= A;
		else 
			state <= next;


	always_comb begin
		case(state)
			A: next = w ? B : A;
			B: next = w ? D : C;
			C: next = w ? F : E;
			D: next = w ? D : A;
			E: next = w ? E : F;
			F: next = w ? A : C;
			default: next = 'x;
		endcase
	end

	assign z = (state == D || state == E || state == F);

endmodule

