module traffic_light (
	input clk,
	input resetn,
	output green,
	output yellow,
	output red);

	parameter GREEN=0, YELLOW=1, RED=2;
	reg [1:0] state, next_state;
	reg [3:0] counter;

	always @(posedge clk) begin
		if (~resetn) state <= GREEN;
		else state <= next_state;
	end

	always @(posedge clk) begin
		if (state == GREEN || state == YELLOW || state == RED) counter <= counter + 1;
		else counter <= 0;
	end

	always_comb begin
		case (state)
			GREEN: next_state = (counter == 4'd9) ? YELLOW : GREEN;
			YELLOW: next_state = (counter == 4'd2) ? RED : YELLOW;
			RED: next_state = (counter == 4'd4) ? GREEN : RED;
			default: next_state = GREEN;
		endcase
	end

	assign green = (state == GREEN);
	assign yellow = (state == YELLOW);
	assign red = (state == RED);
endmodule

