description:
Design a time-to-digital converter (TDC) that measures the time difference between two input signals, signal1 and signal2. The circuit utilizes a counter to track the elapsed time when both signals are high and resets upon the rising edge of either signal. The measured time difference is scaled by a defined resolution, producing a 16-bit digital output. The output is capped at a maximum range to prevent overflow, ensuring that the digital_value reflects the accurate and bounded time difference between the two input signals.
module top_module(
  input signal1,
  input signal2,
  output reg [15:0] digital_value
);

code:
module top_module(
  input signal1,
  input signal2,
  output reg [15:0] digital_value
);parameter resolution = 1; // smallest time difference that can be measured
parameter range = 1000; // maximum time difference that can be measured

reg [15:0] counter;
reg [15:0] time_diff;

always @(posedge signal1 or posedge signal2) begin
  if (signal1 && !signal2) begin
    counter <= 0;
  end else if (!signal1 && signal2) begin
    counter <= 0;
  end else begin
    counter <= counter + 1;
  end
end

always @(posedge signal1 or posedge signal2) begin
  if (signal1 && !signal2) begin
    time_diff <= 0;
  end else if (!signal1 && signal2) begin
    time_diff <= 0;
  end else begin
    time_diff <= counter * resolution;
  end
end

always @(posedge signal1 or posedge signal2) begin
  if (time_diff > range) begin
    digital_value <= range;
  end else begin
    digital_value <= time_diff;
  end
end

endmodule

