    input in6,
    input in7,
    output out
);

    reg mux_out;  // Multiplexer output register

    always @(*) begin
        case (sel)
            3'b000: mux_out = in0;
            3'b001: mux_out = in1;
            3'b010: mux_out = in2;
            3'b011: mux_out = in3;
            3'b100: mux_out = in4;
            3'b101: mux_out = in5;
            3'b110: mux_out = in6;
            3'b111: mux_out = in7;
            default: mux_out = 1'b0;  // Default case (should not occur)
        endcase
    end

    assign out = mux_out;

endmodule

module counter(
	input 	clk,
	input 	rst,
	output reg [2:0] count
);

always @(posedge clk or posedge rst)
begin
	if (rst)
		count <= 3'b000;
	else
		count <= (count == 3'b111) ? 3'b000 : count + 3'b001;
end

endmodule

