description:
Construct a 4-bit binary up-counter with asynchronous reset functionality. The circuit increments its count on each positive clock edge and resets to zero when the RST input is asserted. When the counter reaches its maximum value of 15 (binary 1111), it rolls over back to 0. The current count is output on a 4-bit bus Q.
module top_module(
    input CLK,
    input RST,
    output [3:0] Q
);

code:
module top_module(
    input CLK,
    input RST,
    output [3:0] Q
);// Local signals
    wire [3:0] Q_next;

    // D flip-flops
    reg [3:0] Q_reg;
    always @(posedge CLK) begin
        if (RST) begin
            Q_reg <= 4'b0000;
        end else begin
            Q_reg <= Q_next;
        end
    end

    // Combinational logic
    assign Q_next = (Q_reg == 4'b1111) ? 4'b0000 : Q_reg + 1'b1;
    assign Q = Q_reg;

endmodule

