module top_module(din, clk, rst, q, se, si, so);// synopsys template

parameter SIZE = 1;

input	[SIZE-1:0]	din ;	// data in
input			clk ;	// clk or scan clk
input			rst ;	// reset

output	[SIZE-1:0]	q ;	// output

input			se ;	// scan-enable
input	[SIZE-1:0]	si ;	// scan-input
output	[SIZE-1:0]	so ;	// scan-output

reg 	[SIZE-1:0]	q ;

`ifdef NO_SCAN
always @ (posedge clk)
	q[SIZE-1:0]  <= ((rst) ? {SIZE{1'b0}}  : din[SIZE-1:0] );
`else

// Scan-Enable dominates
always @ (posedge clk)

	q[SIZE-1:0]  <= se ? si[SIZE-1:0] : ((rst) ? {SIZE{1'b0}}  : din[SIZE-1:0] );

assign so[SIZE-1:0] = q[SIZE-1:0] ;
`endif

endmodule

module gray_counter
    (
        input rst_n,
        input clk,
        output reg [2:0] gray_code
    );

    reg [2:0] binary_count;

    always @(posedge clk or negedge rst_n) 
    begin
        if (!rst_n)
            binary_count <= 3'd0;
        else
            binary_count <= binary_count + 1;
    end

    always @(binary_count) 
    begin
        gray_code = binary_count ^ (binary_count >> 1);
    end

endmodule

module top_module(
  input in1,
  input in2,
  input in3,
  output out1
);wire not_in3;
  wire and_in1_in2;
  wire or_and_not;

  assign not_in3 = ~in3;
  assign and_in1_in2 = in1 & in2;
  assign or_and_not = and_in1_in2 | not_in3;

  assign out1 = or_and_not;

endmodule

