module debounce(
    input clk,
    input rst_n,
    input switch_in,
    output reg switch_out
);

reg [3:0] counter;
reg stable_switch;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 4'd0;
        stable_switch <= 0;
    end else if (switch_in == stable_switch) begin
        if (counter < 4'd15)
            counter <= counter + 1;
        else
            switch_out <= switch_in;
    end else begin
        counter <= 4'd0;
        stable_switch <= switch_in;
    end
end

endmodule

module top_module(
    input D,
    input RESET_B,
    input CLK,
    output Q,
    output Q_N
);reg q;
    assign Q = q;
    assign Q_N = ~q;

    always @(posedge CLK or negedge RESET_B) begin
        if (~RESET_B) begin
            q <= 0;
        end else begin
            q <= D;
        end
    end

endmodule

